pub const fn pyke_q(ctx: &Ctx) -> f32 {
    50f32 * (1f32 + 0.015 * ctx.bonus_ad + ctx.q_level)
}

pub const fn pyke_e(ctx: &Ctx) -> f32 {
    100f32 + ctx.bonus_ad + 50f32 * (-1f32 + ctx.e_level)
}

pub const fn pyke_r(ctx: &Ctx) -> f32 {
    ((match ctx.level as u8 {
        ..7 => 250f32,
        7 => 290f32,
        8 => 330f32,
        9 => 370f32,
        10 => 400f32,
        11 => 430f32,
        12 => 450f32,
        13 => 470f32,
        14 => 490f32,
        15 => 510f32,
        16 => 530f32,
        17 => 540f32,
        18.. => 550f32,
    }) + 1.5 * ctx.armor_penetration_flat
        + 0.8 * ctx.bonus_ad)
        / 2f32
}

pub const fn pyke_r1(ctx: &Ctx) -> f32 {
    (match ctx.level as u8 {
        ..7 => 250f32,
        7 => 290f32,
        8 => 330f32,
        9 => 370f32,
        10 => 400f32,
        11 => 430f32,
        12 => 450f32,
        13 => 470f32,
        14 => 490f32,
        15 => 510f32,
        16 => 530f32,
        17 => 540f32,
        18.. => 550f32,
    }) + 1.5 * ctx.armor_penetration_flat
        + 0.8 * ctx.bonus_ad
}

