pub const fn volibear_p1(_: &Ctx) -> f32 {
    0f32
}

pub const fn volibear_p2(ctx: &Ctx) -> f32 {
    (match ctx.level as u8 {
        ..=1 => 11f32,
        2 => 12f32,
        3 => 13f32,
        4 => 15f32,
        5 => 17f32,
        6 => 19f32,
        7 => 22f32,
        8 => 25f32,
        9 => 28f32,
        10 => 31f32,
        11 => 34f32,
        12 => 37f32,
        13 => 40f32,
        14 => 44f32,
        15 => 48f32,
        16 => 52f32,
        17 => 56f32,
        18 => 60f32,
        19 => 64f32,
        20.. => 68f32,
    }) + 0.45 * ctx.ability_power
}

pub const fn volibear_q1(ctx: &Ctx) -> f32 {
    10f32 + 1.6 * ctx.bonus_ad + 10f32 * (-1f32 + ctx.q_level)
}

pub const fn volibear_w1(ctx: &Ctx) -> f32 {
    5f32 + 1.1 * ctx.attack_damage
        + 0.06 * ctx.bonus_health
        + 25f32 * (-1f32 + ctx.w_level)
}

pub const fn volibear_e1(ctx: &Ctx) -> f32 {
    80f32
        + 0.7 * ctx.ability_power
        + 30f32 * (-1f32 + ctx.e_level)
        + ctx.enemy_max_health * (0.11 + 0.01 * (-1f32 + ctx.e_level))
}

pub const fn volibear_e2(ctx: &Ctx) -> f32 {
    5f32 * (30f32 + 0.14 * ctx.ability_power + 23f32 * (-1f32 + ctx.e_level))
}

pub const fn volibear_r1(ctx: &Ctx) -> f32 {
    300f32
        + 1.25 * ctx.ability_power
        + 2.5 * ctx.bonus_ad
        + 200f32 * (-1f32 + ctx.r_level)
}

