pub const fn ziggs_p1(ctx: &Ctx) -> f32 {
    (2f32
        * (match ctx.level as u8 {
            ..=1 => 20f32,
            2 => 24f32,
            3 => 28f32,
            4 => 32f32,
            5 => 36f32,
            6 => 40f32,
            7 => 48f32,
            8 => 56f32,
            9 => 64f32,
            10 => 72f32,
            11 => 80f32,
            12 => 88f32,
            13 => 100f32,
            14 => 112f32,
            15 => 124f32,
            16 => 136f32,
            17 => 148f32,
            18 => 160f32,
            19 => 172f32,
            20.. => 184f32,
        })
        + ctx.ability_power)
        / 2f32
}

pub const fn ziggs_p2(ctx: &Ctx) -> f32 {
    0.875 * ctx.ability_power
}

pub const fn ziggs_q1(ctx: &Ctx) -> f32 {
    80f32
        + 50f32 * (-1f32 + ctx.q_level)
        + ctx.ability_power * (0.6 + 0.05 * (-1f32 + ctx.q_level))
}

pub const fn ziggs_w1(ctx: &Ctx) -> f32 {
    70f32 + 35f32 * (-1f32 + ctx.w_level) + ctx.ability_power / 2f32
}

pub const fn ziggs_e1(ctx: &Ctx) -> f32 {
    30f32
        + 40f32 * (-1f32 + ctx.e_level)
        + ctx.ability_power * (0.25 + 0.05 * (-1f32 + ctx.e_level))
}

pub const fn ziggs_e2(ctx: &Ctx) -> f32 {
    150f32
        + 200f32 * (-1f32 + ctx.e_level)
        + ctx.ability_power * (1.25 + 0.25 * (-1f32 + ctx.e_level))
}

pub const fn ziggs_e3(ctx: &Ctx) -> f32 {
    12f32
        + 16f32 * (-1f32 + ctx.e_level)
        + ctx.ability_power * (0.1 + 0.02 * (-1f32 + ctx.e_level))
}

pub const fn ziggs_r1(ctx: &Ctx) -> f32 {
    300f32 + ctx.ability_power + 200f32 * (-1f32 + ctx.r_level)
}

pub const fn ziggs_r2(ctx: &Ctx) -> f32 {
    65f32 * (3f32 + 0.01 * ctx.ability_power + 2f32 * (-1f32 + ctx.r_level))
}

